-- Seed data for the `spots` table, sourced from real Creatrip listings
-- (scraped page dumps under place_DB/urltotext/, one file per Creatrip spot id).
--
-- Generated from 50 places across dermatology, hair-salon, and
-- k-beauty categories. A handful of scraped ids were excluded: two dermatology
-- listings were Busan branches (out of scope — this catalog is Seoul-only), and
-- a few files were empty scrapes. Several ids filed under the hair_salon/ folder
-- turned out to be k-beauty listings by the page's own category tag, not hair
-- salons — parent_category below reflects the page's real category, not the
-- scrape folder.
--
-- booking_url embeds Miyeon's Creatrip affiliate tracking params (utm_source
-- and aff_id = AFF-e2873zu), matching src/lib/creatrip.ts#withCreatripAffiliate.
--
-- Coordinates were geocoded via OpenStreetMap Nominatim against the scraped
-- address; where no street address was captured in the scrape, coordinates
-- fall back to the named neighborhood/station centroid (see each row's source
-- JSON in the extraction — not preserved here) rather than being fabricated.
-- price_min/price_max/opening_hours/duration_min are left null where the
-- scrape had no reliable figure — most listing pages didn't expose a real
-- price table or venue hours (only unrelated boilerplate), so these were not
-- guessed.
--
-- Run after supabase/spots_schema.sql has created the table.

on conflict (id) do update set
  name = excluded.name,
  parent_category = excluded.parent_category,
  subcategory = excluded.subcategory,
  description = excluded.description,
  area = excluded.area,
  address = excluded.address,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  price_min = excluded.price_min,
  price_max = excluded.price_max,
  duration_min = excluded.duration_min,
  opening_hours = excluded.opening_hours,
  booking_required = excluded.booking_required,
  booking_url = excluded.booking_url,
  languages = excluded.languages,
  downtime = excluded.downtime,
  procedure_intensity = excluded.procedure_intensity,
  needle_required = excluded.needle_required,
  tourist_friendly = excluded.tourist_friendly,
  factory_like = excluded.factory_like,
  upselling_risk = excluded.upselling_risk,
  price_transparency = excluded.price_transparency,
  rating = excluded.rating,
  review_count = excluded.review_count,
  experience_style = excluded.experience_style,
  updated_at = now();
